cd /home/runner/work/flutter_agent_harness/flutter_agent_harness && git diff origin/main...HEAD -- CHANGELOG.md | grep -E '^[+-]' | grep -vE '^(---|\+\+\+)' > /tmp/cl_changes.txt && wc -l /tmp/cl_changes.txt && python3 -c "
import re
lines = open('/tmp/cl_changes.txt', encoding='utf-8').read().splitlines()
minus = [l[1:] for l in lines if l.startswith('-')]
plus = [l[1:] for l in lines if l.startswith('+')]
print('minus lines:', len(minus), 'plus lines:', len(plus))
# de-mojibake the plus lines: encode as cp1251, decode as utf-8 where possible
def repair(s):
    try:
        return s.encode('cp1251').decode('utf-8')
    except Exception:
        return None
changed = 0
unrepairable = []
for p in plus:
    r = repair(p)
    if r is None:
        unrepairable.append(p)
print('plus lines fully repairable:', len(plus)-len(unrepairable))
for u in unrepairable[:20]:
    print('UNREPAIRABLE:', u)
# check whether repaired plus set == minus set
rep_plus = set()
for p in plus:
    r = repair(p)
    rep_plus.add(r if r is not None else p)
minus_set = set(minus)
print('minus set == repaired plus set:', minus_set == rep_plus)
if minus_set != rep_plus:
    print('only in minus:', len(minus_set-rep_plus))
    for l in sorted(minus_set-rep_plus)[:10]: print('  -', l)
    print('only in plus:', len(rep_plus-minus_set))
    for l in sorted(rep_plus-minus_set)[:10]: print('  +', l)
"

