  final ConsoleLineDecoder _decoder;
  final Sink<String> _sink;

  _ConsoleLineChunkedSink(this._decoder, this._sink);

  @override
  void add(List<int> chunk) => _sink.add(_decoder.convert(chunk));

  @override
  void close() => _sink.close();
}

