      final d = ConsoleLineDecoder(runRepair: _repair);
      expect(d.convert(const [0xC3, 0xAF]), 'п');
    });

    test('chars outside the Latin-1 range never repair', () {
      final d = ConsoleLineDecoder(runRepair: _repair);
      expect(d.convert(utf8.encode('ёжик ✓')), 'ёжик ✓');
    });
  });

